import { t } from '@subby/shared/i18n';
import React, { useState } from 'react';
import { FlatList, Pressable, Text, View } from 'react-native';
import { Lead } from '../components/ui';
import { useScreenBottom } from '../components/ScreenScroll';
// Generated by scripts/licenses.mjs: what ships in the app (not the build tools), with each license's text.
import LICENSES from '../assets/licenses.json';

type Package = { name: string; version: string; license: string; url?: string; text?: number };
const PACKAGES = LICENSES.packages as Package[];

/** Settings → Open source licenses: Subby's own licenses, then every open source package the app ships. */
export default function LicensesScreen() {
  const bottom = useScreenBottom();
  const [open, setOpen] = useState<string | null>(null);
  return (
    <FlatList
      className="flex-1 bg-ground"
      contentContainerStyle={{ padding: 16, paddingBottom: bottom }}
      data={PACKAGES}
      keyExtractor={(p) => p.name}
      ListHeaderComponent={<Lead className="mb-4">{t('licenses.lead')}</Lead>}
      renderItem={({ item, index }) => {
        const shown = open === item.name;
        const first = index === 0;
        const last = index === PACKAGES.length - 1;
        return (
          <View className={`bg-surface border-line border-x ${first ? 'border-t rounded-t-2xl' : ''} ${last ? 'border-b rounded-b-2xl' : 'border-b'}`}>
            <Pressable onPress={() => setOpen(shown ? null : item.name)} className="px-4 py-3" accessibilityState={{ expanded: shown }}>
              <Text className="text-ink text-base">{item.name}</Text>
              <Text className="text-ink-muted text-sm mt-0.5">
                {item.version} · {item.license}
              </Text>
            </Pressable>
            {shown && item.text !== undefined ? (
              <Text selectable className="text-ink-soft text-xs leading-[18px] px-4 pb-4">
                {LICENSES.texts[item.text]}
              </Text>
            ) : null}
          </View>
        );
      }}
    />
  );
}
